//Autogenerated by env_kits.py: the environment kits' pieces and the baked ground's layout

/// Every level's cell size in pixels (the Tiled maps' tile size): the pieces, the baked floors and the level files
/// are all made at it, so level_loader rejects a level with any other
pub const CELL_W: u8 = 57;
pub const CELL_H: u8 = 27;

/// Pixels the baked ground bitmap extends beyond the map on each side (it covers the camera's widest lean)
pub const GROUND_MARGIN_X: i32 = 256;
pub const GROUND_MARGIN_Y: i32 = 160;

/// A piece's bitmap size and the pixel that sits on its anchor cell's centre, drawn as is and mirrored
pub const Piece = struct { w: i16, h: i16, anchor_x: i16, anchor_x_flipped: i16, anchor_y: i16 };

pub const Kit = struct { name: [:0]const u8, pieces: []const Piece };

/// Every piece and every level's floor comes in this many phase variants, one per screen pixel phase
pub const PHASES = 4;

